#include <algorithm>
#include <cstddef>
#include <initializer_list>
#include <memory>
#include <stdexcept>
#include <utility>

class IntVector
{
public:
    static constexpr std::size_t maxSize() { return std::size_t{ 1 } << 28; }

    IntVector() = default;

    explicit IntVector(std::size_t count, int value = 0)
        : data_{ count > 0 ? std::make_unique<int[]>(count) : nullptr }, size_{ count }, capacity_{ count }
    {
        std::fill_n(data_.get(), count, value);
    }

    IntVector(std::initializer_list<int> values) : IntVector(values.size())
    {
        std::copy(values.begin(), values.end(), data_.get());
    }

    IntVector(const IntVector& other) : IntVector(other.size_)
    {
        std::copy_n(other.data_.get(), other.size_, data_.get());
    }

    IntVector(IntVector&& other) noexcept
        : data_{ std::move(other.data_) }, size_{ std::exchange(other.size_, 0) }, capacity_{ std::exchange(other.capacity_, 0) }
    {
    }

    IntVector& operator=(const IntVector& other)
    {
        if (this != &other)
        {
            IntVector copy(other);
            swap(copy);
        }
        return *this;
    }

    IntVector& operator=(IntVector&& other) noexcept
    {
        IntVector taken(std::move(other));
        swap(taken);
        return *this;
    }

    std::size_t size() const { return size_; }
    std::size_t capacity() const { return capacity_; }
    bool empty() const { return size_ == 0; }
    int* data() { return data_.get(); }

    int& operator[](std::size_t i) { return data_[i]; }

    int& at(std::size_t i)
    {
        if (i >= size_) throw std::out_of_range("IntVector::at");
        return data_[i];
    }

    int& front() { return data_[0]; }
    int& back() { return data_[size_ - 1]; }

    void push_back(int value)
    {
        if (size_ == capacity_) reallocate(std::max<std::size_t>(1, 2 * capacity_));
        data_[size_++] = value;
    }

    void pop_back() { --size_; }

    std::size_t insert(std::size_t pos, int value)
    {
        if (pos > size_) throw std::out_of_range("IntVector::insert");
        if (size_ == capacity_) reallocate(std::max<std::size_t>(1, 2 * capacity_));
        std::copy_backward(data_.get() + pos, data_.get() + size_, data_.get() + size_ + 1);
        data_[pos] = value;
        ++size_;
        return pos;
    }

    std::size_t insert(std::size_t pos, std::size_t count, int value)
    {
        if (pos > size_) throw std::out_of_range("IntVector::insert");
        if (count == 0) return pos;
        if (size_ + count > capacity_) reallocate(std::max(2 * capacity_, size_ + count));
        std::copy_backward(data_.get() + pos, data_.get() + size_, data_.get() + size_ + count);
        std::fill_n(data_.get() + pos, count, value);
        size_ += count;
        return pos;
    }

    std::size_t erase(std::size_t pos)
    {
        if (pos >= size_) throw std::out_of_range("IntVector::erase");
        std::copy(data_.get() + pos + 1, data_.get() + size_, data_.get() + pos);
        --size_;
        return pos;
    }

    std::size_t erase(std::size_t first, std::size_t last)
    {
        if (first > last || last > size_) throw std::out_of_range("IntVector::erase");
        std::copy(data_.get() + last, data_.get() + size_, data_.get() + first);
        size_ -= last - first;
        return first;
    }

    void resize(std::size_t n, int value = 0)
    {
        if (n > capacity_) reallocate(n);
        if (n > size_) std::fill_n(data_.get() + size_, n - size_, value);
        size_ = n;
    }

    void reserve(std::size_t n)
    {
        if (n > maxSize()) throw std::length_error("IntVector::reserve");
        if (n > capacity_) reallocate(n);
    }

    void shrinkToFit()
    {
        if (capacity_ != size_) reallocate(size_);
    }

    void clear() { size_ = 0; }

    bool operator==(const IntVector& other) const
    {
        return size_ == other.size_ && std::equal(data_.get(), data_.get() + size_, other.data_.get());
    }

private:
    void reallocate(std::size_t newCapacity)
    {
        std::unique_ptr<int[]> fresh{ newCapacity > 0 ? std::make_unique<int[]>(newCapacity) : nullptr };
        std::copy_n(data_.get(), size_, fresh.get());
        data_ = std::move(fresh);
        capacity_ = newCapacity;
    }

    void swap(IntVector& other) noexcept
    {
        std::swap(data_, other.data_);
        std::swap(size_, other.size_);
        std::swap(capacity_, other.capacity_);
    }

    std::unique_ptr<int[]> data_;
    std::size_t size_{ 0 };
    std::size_t capacity_{ 0 };
};

unitTests:
bool holds(IntVector& v, std::initializer_list<int> expected) {
    if (v.size() != expected.size()) return false;
    std::size_t i{ 0 };
    for (int x : expected) if (v[i++] != x) return false;
    return true;
}
TEST("constructing") {
    IntVector a;
    CHECK(a.empty() && a.size() == 0 && a.capacity() == 0);
    IntVector b(3, 7);
    CHECK(holds(b, { 7, 7, 7 }) && b.capacity() == 3);
    IntVector c{ 1, 2, 3 };
    CHECK(holds(c, { 1, 2, 3 }) && c.capacity() == 3);
    IntVector d{ 3 };
    CHECK(holds(d, { 3 }));
    IntVector e(3);
    CHECK(holds(e, { 0, 0, 0 }));
}
TEST("checked and unchecked access") {
    IntVector v{ 10, 20, 30 };
    CHECK_EQ(v.at(2), 30);
    v.at(0) = 11;
    CHECK_EQ(v[0], 11);
    CHECK_EQ(v.front(), 11);
    CHECK_EQ(v.back(), 30);
    CHECK_THROWS_AS(v.at(3), std::out_of_range);
    IntVector empty;
    CHECK_THROWS_AS(empty.at(0), std::out_of_range);
}
TEST("capacity grows by doubling") {
    IntVector v;
    std::size_t seen[5]{};
    for (int i{ 0 }; i < 5; ++i) { v.push_back(i); seen[i] = v.capacity(); }
    CHECK(seen[0] == 1 && seen[1] == 2 && seen[2] == 4 && seen[3] == 4 && seen[4] == 8);
    CHECK(holds(v, { 0, 1, 2, 3, 4 }));
    v.pop_back();
    CHECK(holds(v, { 0, 1, 2, 3 }) && v.capacity() == 8);
}
TEST("no reallocation within capacity") {
    IntVector v;
    v.reserve(100);
    const int* before{ v.data() };
    for (int i{ 0 }; i < 100; ++i) v.push_back(i);
    CHECK(v.data() == before);
    CHECK_EQ(v.capacity(), 100u);
    v.push_back(100);
    CHECK_EQ(v.capacity(), 200u);
    long long sum{ 0 };
    for (std::size_t i{ 0 }; i < v.size(); ++i) sum += v[i];
    CHECK_EQ(sum, 5050);
}
TEST("inserting") {
    IntVector v{ 1, 2, 3 };
    CHECK_EQ(v.insert(0, 9), 0u);
    CHECK(holds(v, { 9, 1, 2, 3 }) && v.capacity() == 6);
    CHECK_EQ(v.insert(4, 4), 4u);
    CHECK(holds(v, { 9, 1, 2, 3, 4 }));
    CHECK_EQ(v.insert(1, 3, 0), 1u);
    CHECK(holds(v, { 9, 0, 0, 0, 1, 2, 3, 4 }) && v.capacity() == 12);
    CHECK_EQ(v.insert(2, 0, 5), 2u);
    CHECK_EQ(v.size(), 8u);
    IntVector w{ 1 };
    w.insert(1, 10, 2);
    CHECK_EQ(w.capacity(), 11u);
    CHECK_THROWS_AS(v.insert(9, 1), std::out_of_range);
    CHECK_THROWS_AS(v.insert(9, 2, 1), std::out_of_range);
    CHECK_EQ(v.size(), 8u);
    IntVector e;
    e.insert(0, 5);
    CHECK(holds(e, { 5 }) && e.capacity() == 1);
}
TEST("erasing") {
    IntVector v{ 0, 1, 2, 3, 4, 5 };
    CHECK_EQ(v.erase(0), 0u);
    CHECK(holds(v, { 1, 2, 3, 4, 5 }));
    CHECK_EQ(v.erase(1, 3), 1u);
    CHECK(holds(v, { 1, 4, 5 }) && v.capacity() == 6);
    CHECK_EQ(v.erase(2, 2), 2u);
    CHECK_THROWS_AS(v.erase(3), std::out_of_range);
    CHECK_THROWS_AS(v.erase(2, 1), std::out_of_range);
    CHECK_THROWS_AS(v.erase(0, 4), std::out_of_range);
    CHECK(holds(v, { 1, 4, 5 }));
    CHECK_EQ(v.erase(0, 3), 0u);
    CHECK(v.empty());
}
TEST("resizing, reserving, shrinking and clearing") {
    IntVector v{ 1, 2 };
    v.resize(5, 9);
    CHECK(holds(v, { 1, 2, 9, 9, 9 }) && v.capacity() == 5);
    v.resize(1);
    CHECK(holds(v, { 1 }) && v.capacity() == 5);
    v.reserve(3);
    CHECK_EQ(v.capacity(), 5u);
    v.reserve(40);
    CHECK_EQ(v.capacity(), 40u);
    CHECK_THROWS_AS(v.reserve(IntVector::maxSize() + 1), std::length_error);
    CHECK(holds(v, { 1 }) && v.capacity() == 40);
    v.shrinkToFit();
    CHECK_EQ(v.capacity(), 1u);
    v.push_back(2);
    v.clear();
    CHECK(v.empty() && v.capacity() == 2);
    v.shrinkToFit();
    CHECK_EQ(v.capacity(), 0u);
}
TEST("copies and moves") {
    IntVector a{ 1, 2, 3 };
    a.reserve(10);
    IntVector b(a);
    CHECK(b == a && b.capacity() == 3);
    b[0] = 100;
    CHECK(a[0] == 1 && !(a == b));
    IntVector c;
    c = a;
    CHECK(c == a);
    c = c;
    CHECK(c == a);
    IntVector d(std::move(a));
    CHECK(holds(d, { 1, 2, 3 }) && d.capacity() == 10);
    CHECK(a.empty() && a.capacity() == 0);
    IntVector e{ 9 };
    e = std::move(d);
    CHECK(holds(e, { 1, 2, 3 }));
    CHECK(d.empty() && d.capacity() == 0);
    CHECK(IntVector{} == IntVector(0));
    CHECK(!(IntVector{ 1, 2 } == IntVector{ 1, 3 }));
}

